//! The differential test: the Rust head must reproduce `PyTorch`'s own output.
//!
//! The fixture is generated by `scripts/make-head-fixture.py`, which runs the **real**
//! `nn.TransformerEncoderLayer` / `nn.Sequential` modules the checkpoint was trained with over
//! synthetic hidden states. Nothing here re-implements the reference, so a match is evidence
//! and a mismatch is a real difference.
//!
//! ## Why this is the strongest oracle available offline
//!
//! The head is a pure function of `(hidden, qtype, markers)` plus weights. Only the *backbone*
//! needs the live model, so the head can be tested exactly, with no network and no Python at
//! test time.
//!
//! ## The tolerance, and why it is not "as tight as possible"
//!
//! The port accumulates in `f64` inside `LayerNorm` and sums dot products in index order, while
//! `PyTorch` uses its own kernels. A bit-exact match was not expected, so the assertion is
//! against a tolerance **derived from what the decision actually depends on**: the logits feed
//! a softmax and then a near-tie comparison, and the margin scale is 1e-3. A logit error of
//! 1e-4 is therefore far below anything that could move a label — and the test asserts that
//! claim separately (`the_tolerance_cannot_move_a_label`).

// A test should fail loudly (`unwrap`/`expect`/`panic`), it indexes small fixed slices it
// constructs itself, and it compares f32 magnitudes against f64 constants.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::cast_possible_truncation,
    clippy::single_char_lifetime_names
)]

use laya_head::forward::Head;
use laya_head::safetensors::SafetensorsFile;
use std::path::Path;

const FIXTURE: &str = "tests/fixtures/head_forward.json";
const REAL_HEAD: &str = "/projects/_tmp/laya-gguf/laya-head.safetensors";

/// The largest LOGIT difference the port is allowed.
///
/// The logits drive the label, via `softmax` and then a near-tie comparison whose margin scale
/// is 1e-3. 1e-4 is an order below that, and `the_tolerance_cannot_move_a_label` measures the
/// consequence rather than assuming it.
const LOGIT_TOL: f32 = 1e-4;

/// The largest ACT-logit difference, which is a **different and much looser** bound, and the
/// reason is worth stating because the first version of this test used one tolerance for both
/// and failed.
///
/// The act logits are ~3000 in magnitude (the head's blocks produce large activations), and the
/// port accumulates in `f64` while `PyTorch` uses its own kernels — so a relative difference of
/// ~1.5e-6 is expected, not a defect. What matters is the consequence: these logits feed a
/// `softmax` whose output is `act_probability`, and that value is **inert** in this project —
/// measured at exactly 1.0 on the live model, because the two logits differ by thousands and the
/// softmax saturates. So the assertion below is on the *probability*, with the raw bound kept
/// loose and derived from the magnitudes involved.
const ACT_TOL: f32 = 1e-2;

struct Case {
    name: String,
    seq: usize,
    qtype: usize,
    marker_pos: Vec<usize>,
    marker_mask: Vec<bool>,
    hidden: Vec<f32>,
    logits: Vec<f32>,
    act_logits: Vec<f32>,
}

/// Two-way softmax over a 2-element slice, for the `act_probability` assertion.
fn softmax2(logits: &[f32]) -> [f32; 2] {
    let (first, second) = (
        logits.first().copied().unwrap_or(0.0),
        logits.get(1).copied().unwrap_or(0.0),
    );
    let peak = first.max(second);
    let (e_first, e_second) = ((first - peak).exp(), (second - peak).exp());
    let total = e_first + e_second;
    if total > 0.0 {
        [e_first / total, e_second / total]
    } else {
        [0.5, 0.5]
    }
}

fn load_fixture() -> Option<(usize, Vec<Case>)> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(root.join(FIXTURE)).ok()?;
    let v: serde_json::Value = serde_json::from_str(&text).ok()?;
    let d = v["d"].as_u64()? as usize;
    let mut cases = Vec::new();
    for c in v["cases"].as_array()? {
        let nums = |k: &str| -> Vec<f32> {
            c[k].as_array()
                .map(|a| {
                    a.iter()
                        .map(|x| x.as_f64().unwrap_or(f64::NAN) as f32)
                        .collect()
                })
                .unwrap_or_default()
        };
        cases.push(Case {
            name: c["name"].as_str().unwrap_or("?").to_string(),
            seq: c["seq"].as_u64().unwrap_or(0) as usize,
            qtype: c["qtype"].as_u64().unwrap_or(0) as usize,
            marker_pos: c["marker_pos"]
                .as_array()
                .map(|a| a.iter().map(|x| x.as_u64().unwrap_or(0) as usize).collect())
                .unwrap_or_default(),
            marker_mask: c["marker_mask"]
                .as_array()
                .map(|a| a.iter().map(|x| x.as_bool().unwrap_or(false)).collect())
                .unwrap_or_default(),
            hidden: nums("hidden"),
            logits: nums("logits"),
            act_logits: nums("act_logits"),
        });
    }
    Some((d, cases))
}

/// Load the real checkpoint, or `None` when it is absent (a clean checkout, or CI).
fn real_head() -> Option<Head> {
    let file = SafetensorsFile::open(Path::new(REAL_HEAD)).ok()?;
    Head::load(&file).ok()
}

#[test]
fn the_port_reproduces_pytorchs_logits() {
    let Some((d, cases)) = load_fixture() else {
        eprintln!("SKIP: fixture absent — run scripts/make-head-fixture.py");
        return;
    };
    let Some(head) = real_head() else {
        eprintln!("SKIP: checkpoint absent at {REAL_HEAD}");
        return;
    };
    assert_eq!(
        head.d(),
        d,
        "the fixture and the checkpoint must agree on d"
    );

    let mut worst = 0.0_f32;
    for case in &cases {
        assert_eq!(
            case.hidden.len(),
            case.seq * d,
            "{}: fixture hidden length",
            case.name
        );
        let (got, act) = head
            .forward(
                &case.hidden,
                case.qtype,
                &case.marker_pos,
                &case.marker_mask,
            )
            .expect("forward");
        assert_eq!(got.len(), case.logits.len(), "{}: logit count", case.name);

        for (i, (g, w)) in got.iter().zip(&case.logits).enumerate() {
            let diff = (g - w).abs();
            worst = worst.max(diff);
            assert!(
                diff < LOGIT_TOL,
                "{}: logit[{i}] = {g}, PyTorch says {w} (diff {diff:e} > {LOGIT_TOL:e})\n\
                 got      {got:?}\n\
                 expected {:?}",
                case.name,
                case.logits
            );
        }
        for (i, (g, w)) in act.iter().zip(&case.act_logits).enumerate() {
            let diff = (g - w).abs();
            assert!(
                diff < ACT_TOL,
                "{}: act_logit[{i}] = {g}, PyTorch says {w} (diff {diff:e} > {ACT_TOL:e})",
                case.name
            );
        }
        // The consequence, which is what the tolerance is for: after the softmax the port must
        // agree with PyTorch on `act_probability` far more tightly than the logits do, because
        // the softmax is saturated. If this ever failed, `ACT_TOL` would be hiding a real
        // divergence.
        let (gp, wp) = (softmax2(&act), softmax2(&case.act_logits));
        for i in 0..2 {
            let d = (gp[i] - wp[i]).abs();
            assert!(
                d < 1e-6,
                "{}: act_probability[{i}] differs by {d:e} (port {} vs torch {}) — the act logit \
                 tolerance is hiding a real difference",
                case.name,
                gp[i],
                wp[i]
            );
        }
    }
    eprintln!(
        "worst logit difference across {} cases: {worst:e}",
        cases.len()
    );
}

/// The claim that makes `LOGIT_TOL` acceptable, as a measurement rather than an assurance.
///
/// A logit error only matters if it can change the *label*, and the label comes from an argmax
/// over probabilities. This test perturbs the winning logit by the full tolerance and asserts
/// the winner does not change, on every fixture case.
#[test]
fn the_tolerance_cannot_move_a_label() {
    let Some((_d, cases)) = load_fixture() else {
        return;
    };
    let Some(head) = real_head() else {
        return;
    };
    for case in &cases {
        let (got, _) = head
            .forward(
                &case.hidden,
                case.qtype,
                &case.marker_pos,
                &case.marker_mask,
            )
            .expect("forward");
        let argmax = |values: &[f32]| {
            values
                .iter()
                .enumerate()
                .max_by(|left, right| {
                    left.1
                        .partial_cmp(right.1)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .map_or(0, |(index, _)| index)
        };
        let winner = argmax(&got);
        // Push the winning logit DOWN by the tolerance: the label must survive.
        let mut lowered = got.clone();
        lowered[winner] -= LOGIT_TOL;
        assert_eq!(
            argmax(&lowered),
            winner,
            "{}: a logit error of {LOGIT_TOL:e} changed the label — the tolerance is too loose",
            case.name
        );
    }
}

/// The port must be a pure function of its inputs (F11): calling twice must give identical
/// results, and calling on a shared reference from two threads must too.
///
/// The second half is the one that matters — it is what makes the pool in front of the head
/// safe without a lock.
#[test]
fn the_forward_pass_is_pure_and_shareable() {
    let Some((_d, cases)) = load_fixture() else {
        return;
    };
    let Some(head) = real_head() else {
        return;
    };
    let case = &cases[0];
    let first = head
        .forward(
            &case.hidden,
            case.qtype,
            &case.marker_pos,
            &case.marker_mask,
        )
        .expect("forward");
    let second = head
        .forward(
            &case.hidden,
            case.qtype,
            &case.marker_pos,
            &case.marker_mask,
        )
        .expect("forward");
    assert_eq!(first.0, second.0, "same input, same output");
    assert_eq!(first.1, second.1);

    // Shared by reference across threads: needs no lock, because `forward` is `&self`.
    let shared = &head;
    let (a, b) = std::thread::scope(|s| {
        let h1 = s.spawn(|| {
            shared.forward(
                &case.hidden,
                case.qtype,
                &case.marker_pos,
                &case.marker_mask,
            )
        });
        let h2 = s.spawn(|| {
            shared.forward(
                &case.hidden,
                case.qtype,
                &case.marker_pos,
                &case.marker_mask,
            )
        });
        (h1.join().expect("thread"), h2.join().expect("thread"))
    });
    assert_eq!(
        a.expect("forward").0,
        b.expect("forward").0,
        "two threads sharing one head must agree bit-for-bit"
    );
}

/// Every tensor the forward pass reads must be present, and this is F1's "all 36" requirement.
#[test]
fn every_tensor_the_head_reads_is_in_the_checkpoint() {
    let Ok(checkpoint) = SafetensorsFile::open(Path::new(REAL_HEAD)) else {
        eprintln!("SKIP: checkpoint absent");
        return;
    };
    let head = Head::load(&checkpoint).expect("load");
    let d = head.d();
    let expected = laya_head::forward::expected_tensor_names(d, 4 * d);
    let present: std::collections::BTreeSet<String> = checkpoint
        .tensors()
        .iter()
        .map(|v| v.name.clone())
        .collect();
    for name in expected.keys() {
        assert!(
            present.contains(name),
            "the forward pass reads `{name}` but the checkpoint does not have it"
        );
    }
    // And the count, as F1 states it.
    assert_eq!(
        present.len(),
        36,
        "the checkpoint has {} tensors, and the spec says 36",
        present.len()
    );
    // 35 are weights; `temperature` is a buffer the forward pass does not read but the spec
    // requires loading. Assert the forward pass needs 35 so the arithmetic is visible.
    assert_eq!(expected.len(), 35, "weights the forward pass reads");
    assert!(present.contains("temperature"), "the 36th, a buffer");
}

/// A missing tensor must be a NAMED error, not a zeroed sub-head deciding silently.
#[test]
fn a_missing_tensor_is_refused_by_name() {
    // Build a checkpoint-shaped file with one tensor removed, from the real one's header.
    let Ok(_checkpoint) = SafetensorsFile::open(Path::new(REAL_HEAD)) else {
        eprintln!("SKIP: checkpoint absent");
        return;
    };
    // The real file loads; a load from a file with `scorer.3.bias` removed is exercised by the
    // safetensors tests, which build malformed headers. Here, assert the error TYPE names the
    // tensor, which is the property this test is about.
    let err = laya_head::forward::HeadError::MissingTensor("scorer.3.bias".into());
    assert!(
        err.to_string().contains("scorer.3.bias"),
        "the error must name the tensor: {err}"
    );
}
